29	// Substitute every count whose label is present. Returns the new text, whether it
30	// differs, and the labels that were NOT found.
31	//
32	// A missing label is reported rather than appended: the entry is gone because a
33	// person rewrote the stats block, and a machine that adds its own row back is
34	// overruling that edit rather than maintaining it.
35	export function applyStats(text, counts) {
